/**
 * Map a model id string (ctx.getChatCompletionModel() / chat completion settings) to a slop profile.
 * deepseek + (r1|reasoner) -> deepseek-r1; deepseek -> deepseek-v4; glm -> glm-5; kimi|moonshot -> kimi-k2;
 * mimo + 2.6 -> mimo-2.6-pro; mimo -> mimo-2.5; anything else -> common.
 */
export function profileForModel(model) {
    const m = String(model ?? '').toLowerCase();
    if (!m) return 'common';
    if (m.includes('deepseek')) return /(?:^|[^a-z0-9])r1(?![0-9])|reasoner/.test(m) ? 'deepseek-r1' : 'deepseek-v4';
    if (m.includes('glm') || m.includes('zhipu')) return 'glm-5';
    if (m.includes('kimi') || m.includes('moonshot')) return 'kimi-k2';
    if (m.includes('mimo')) return /2[.\-_]?6/.test(m) ? 'mimo-2.6-pro' : 'mimo-2.5';
    return 'common';
}

/** Common list plus the profile's own list. */
export function slopListFor(profile) {
    const own = profile && profile !== 'common' && SLOP[profile] ? SLOP[profile] : [];
    return [...SLOP.common, ...own];
}
